+test("cooking bechamel takes the milk that expires first (HD-1022 before HD-1026)", () => {
+  const store = fresh();
+  const bechamel = store.data.recipes.find((r) => /bechamel/i.test(r.name));
+  const lot = (name) => store.data.batches.find((b) => b.lot === name);
+  const milkNeed = bechamel.ingredients.find((i) => i.itemId === lot("HD-1022").itemId).qty;
+  assert.ok(milkNeed <= 2, "one batch of bechamel fits in lot HD-1022");
+  const newBefore = lot("HD-1026").qty;
+  cook(store, bechamel.id, bechamel.portions, { at });
+  assert.equal(lot("HD-1022").qty, Math.round((2 - milkNeed) * 1000) / 1000);
